local p = {}
local bool_false = { ['false'] = true, ['no'] = true, [''] = true, ['0'] = true, ['nil'] = true } local bool_true = { ['true'] = true, ['yes'] = true }
local lang = mw.getLanguage('en')
function p.merge() local f = mw.getCurrentFrame() local origArgs = f.args
local parent = f:getParent() local parentArgs = parent and parent.args or {}
local args = {}
for k, v in pairs(origArgs) do v = mw.text.trim(tostring(v)) if v ~= '' then args[k] = v end end
for k, v in pairs(parentArgs) do v = mw.text.trim(v) if v ~= '' then args[k] = v end end
return args end
function p.castAsBool(str) if type(str) == 'boolean' then return str end if not str or bool_false[lang:lc(str)] then return false end return true end
return p

return { ResetHourUTC = 17, -- 5PM UTC = 10AM PST ResetMinuteUTC = 0, ResetYear = 2026, ResetMonth = 8, ResetDay = 13,
BiomeData = { airport = { name = 'Airport' }, alpine = { name = 'Alpine' }, caldera = { name = 'Caldera' }, kiln = { name = 'Kiln' }, mesa = { name = 'Mesa' }, peak = { name = 'Peak', page = 'Peak (biome)' }, roots = { name = 'Roots' }, beach = { name = 'Shore' }, shore = { name = 'Shore' }, tropics = { name = 'Tropics' }, gloom = { name = 'Gloom' }, citadel = { name = 'Citadel' }, beach = { name = 'Shore' }, },
BiomeVariations = { -- Level_5 from 2026-08-13 to 2026-08-14 { 'shore', 'tropics', 'alpine', 'gloom', 'citadel' }, -- Level_6 from 2026-08-14 to 2026-08-15 { 'shore', 'roots', 'alpine', 'gloom', 'citadel' }, -- Level_7 from 2026-08-15 to 2026-08-16 { 'shore', 'roots', 'mesa', 'gloom', 'citadel' }, -- Level_8 from 2026-08-16 to 2026-08-17 { 'shore', 'tropics', 'mesa', 'gloom', 'citadel' }, -- Level_9 from 2026-08-17 to 2026-08-18 { 'shore', 'roots', 'alpine', 'gloom', 'citadel' }, -- Level_10 from 2026-08-18 to 2026-08-19 { 'shore', 'roots', 'mesa', 'gloom', 'citadel' }, -- Level_11 from 2026-08-19 to 2026-08-20 { 'shore', 'tropics', 'alpine', 'gloom', 'citadel' }, -- Level_0 from 2026-08-20 to 2026-08-21 { 'shore', 'tropics', 'alpine', 'gloom', 'citadel' }, -- Level_1 from 2026-08-21 to 2026-08-22 { 'shore', 'roots', 'mesa', 'gloom', 'citadel' }, -- Level_2 from 2026-08-22 to 2026-08-23 { 'shore', 'tropics', 'mesa', 'gloom', 'citadel' }, -- Level_3 from 2026-08-23 to 2026-08-24 { 'shore', 'roots', 'alpine', 'gloom', 'citadel' }, -- Level_4 from 2026-08-24 to 2026-08-25 { 'shore', 'tropics', 'mesa', 'gloom', 'citadel' }, }, }

local data = mw.loadData( 'Module:MapTimer/data' )
local htmlencodeMap = {
	['>'] = '&gt;',
	['<'] = '&lt;',
	['&'] = '&amp;',
	['"'] = '&quot;',
}


local function htmlEncode( s )
	return string.gsub( s, '[<>&"]', htmlencodeMap )
end


local function printAttributes()
	local encodedData = mw.text.jsonEncode( data )
	return string.format( 'data-config="%s"', htmlEncode( encodedData ) )
end


return {
	printAttributes = printAttributes,
}
